?>
<?= App\Core\View::render('panel/rounds/_nav', ['tab' => 'rutas', 'subtitle' => 'Recorridos: qué puntos, en qué orden y qué guardias los hacen. Tocá una ruta para verla en el mapa'], null) ?>
<div class="table-responsive mb-4"><table class="table table-sm align-middle"><thead><tr><th>Ruta</th><th>Orden</th><th>Puntos</th><th>Duración esperada</th><th></th></tr></thead><tbody><?php foreach ($routes as $r): ?><tr><td><a href="<?= e(url('/panel/rondas/rutas/' . $r['uuid'])) ?>"><?= e($r['name']) ?></a><?= (int) $r['is_active'] === 1 ? '' : ' <span class="badge text-bg-secondary">Inactiva</span>' ?></td><td><?= e(['libre' => 'Libre', 'secuencial' => 'Secuencial', 'azar' => 'Al azar'][$r['order_mode'] ?? 'libre'] ?? 'Libre') ?></td><td><?= e($r['point_count']) ?></td><td><?= $r['expected_minutes'] ? e($r['expected_minutes']) . ' min' : '—' ?></td><td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/panel/rondas/rutas/' . $r['uuid'])) ?>">Ver en el mapa</a><?php if (!empty($canEdit)): ?> <a class="btn btn-sm btn-outline-primary" href="<?= e(url('/panel/rondas/rutas/' . $r['uuid'] . '/editar')) ?>">Editar</a> <form method="post" action="<?= e(url('/panel/rondas/rutas/' . $r['uuid'] . '/eliminar')) ?>" class="d-inline" onsubmit="return confirm('¿Eliminar la ruta <?= e($r['name']) ?>? Deja de llegar a los celulares y se anulan sus rondas programadas. Las rondas ya hechas quedan en el historial.')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Eliminar</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$routes): ?><tr><td colspan="5" class="text-body-secondary">No hay rutas creadas.</td></tr><?php endif; ?></tbody></table></div>
